)

type PolicyServer struct {
	iampb.UnimplementedPolicyServiceServer
	Store policy.Store
}

func (s *PolicyServer) UpdateRolePermissions(ctx context.Context, req *iampb.UpdateRolePermissionsRequest) (*iampb.RoleResponse, error) {
	// BOLA: Reads tenantId from request message instead of extracting tenant context from authenticated gRPC token.
	role, err := s.Store.AssignPermissions(ctx, req.GetTenantId(), req.GetRoleId(), req.GetPermissions())
