corrected_code:
package iam

import (
	"context"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
	iampb "myapp/gen/iam/v1"
	"myapp/auth"
	"myapp/policy"
)

type PolicyServer struct {
	iampb.UnimplementedPolicyServiceServer
	Store policy.Store
}

func (s *PolicyServer) UpdateRolePermissions(ctx context.Context, req *iampb.UpdateRolePermissionsRequest) (*iampb.RoleResponse, error) {
	callerTenantID, ok := auth.GetTenantFromContext(ctx)
	if !ok {
		return nil, status.Error(codes.Unauthenticated, "Missing tenant authentication")
	}

	if callerTenantID != req.GetTenantId() {
		return nil, status.Error(codes.PermissionDenied, "Cross-tenant policy mutation forbidden")
	}

	role, err := s.Store.AssignPermissions(ctx, callerTenantID, req.GetRoleId(), req.GetPermissions())
	if err != nil {
		return nil, status.Errorf(codes.Internal, "Failed to update permissions: %v", err)
	}

	return &iampb.RoleResponse{RoleId: role.ID, Updated: true}, nil
}
